insert into public.excedentes_de_para
  (empresa_id, cod_recorrente, descricao_recorrente, n_cod_serv_recorrente,
   cod_excedente, descricao_excedente, n_cod_serv_excedente,
   categoria_excedente, origem, status)
select oystr.id, d.cod_recorrente, d.descricao_recorrente,
       d.n_cod_serv_recorrente::bigint, d.cod_excedente,
       d.descricao_excedente, d.n_cod_serv_excedente::bigint,
       d.categoria_excedente, d.origem, d.status
from dados d, oystr
on conflict (empresa_id, cod_recorrente) do nothing;
